import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";

export default function Home() {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeIndex, setActiveIndex] = useState(0);
  const [data, setData] = useState({});

  // ✅ 1️⃣ Always call hooks at the top
  useEffect(() => {
    const fetchHome = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/home");
        setContent(res.data);
      } catch (err) {
        console.error("❌ Error fetching home data:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchHome();
  }, []);

  // ✅ 2️⃣ Activity slider auto-rotation (safe even if content is null)
  useEffect(() => {
    if (content?.activities?.length > 1) {
      const interval = setInterval(() => {
        setActiveIndex((prev) => (prev + 1) % content.activities.length);
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [content]);

  // ✅ 3️⃣ Render safely
  if (loading) return <div className="text-center mt-10">Loading...</div>;
  if (!content) return <div className="text-center mt-10">No content found</div>;

  const { welcomeText, bannerVideos = [], activities = [], testimonialVideos = [] } = content;

  return (
    <div className="home-container">
      {/* 🟢 Banner Section */}
      <section className="banner-section">
        {bannerVideos.length > 0 ? (
          bannerVideos.map((video, i) => (
            <video
              key={i}
              src={`http://localhost:5000${video}`}
              className="banner-video"
              autoPlay
              muted
              loop
              playsInline
            />
          ))
        ) : (
          <div className="no-banner">No banner video uploaded yet</div>
        )}
      </section>

      {/* 🟢 Welcome + Activities (2-column layout) */}
      <section className="welcome-activities">
        {/* Left: Welcome text with HTML support */}
        <div
          className="welcome-text"
          dangerouslySetInnerHTML={{ __html: welcomeText }}
        ></div>

        {/* Right: Activities Carousel */}
        <div className="activities-carousel">
          {activities.length > 0 ? (
            <div className="carousel-frame">
              <img
                src={`http://localhost:5000${activities[activeIndex]}`}
                alt="Activity"
                className="carousel-image"
              />
            </div>
          ) : (
            <p>No activity images uploaded</p>
          )}
        </div>
      </section>

      {/* 🟢 Testimonials Section */}
      <section className="testimonial-section">
        <h2>💬 Student Testimonials</h2>
        <div className="testimonial-grid">
          {data.testimonialVideos?.length > 0 ? (
            data.testimonialVideos.map((vid, i) => (
              <div key={i} className="testimonial-card">
                <video
                  className="testimonial-video"
                  src={vid}
                  controls
                />
                {/* Optional caption */}
                {/* <p className="testimonial-caption">Student {i + 1}</p> */}
              </div>
            ))
          ) : (
            <p>No testimonials yet.</p>
          )}
        </div>
      </section>

    </div>
  );
}
